import{_ as a,s as t,w as l,a3 as e}from"./chunks/plugin-vue_export-helper.B1-2ciIg.js";const p=JSON.parse('{"title":"CoolPotOS","description":"","frontmatter":{},"headers":[],"relativePath":"usr/install.md","filePath":"usr/install.md"}'),i={name:"usr/install.md"};function r(n,o,c,s,h,d){return l(),t("div",null,o[0]||(o[0]=[e('<h1 id="coolpotos" tabindex="-1">CoolPotOS <a class="header-anchor" href="#coolpotos" aria-label="Permalink to &quot;CoolPotOS&quot;">​</a></h1><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>CoolPotOS是一个适用于 x86 平台的宏内核操作系统, 使用MIT开源协议。<br> 开源链接: <a href="https://github.com/plos-clan/CoolPotOS" target="_blank" rel="noreferrer">github.com/plos-clan/CoolPotOS</a> <br> 目前拥有三个版本:</p><ul><li>CoolPotOS i386 - 32位版本,是第一个版本也是目前功能最完善，贡献者最多的版本</li><li>CoolPotOS x86_64 - 64位版本,是目前主要开发的版本, 也是相对来说最符合现代操作系统的</li><li>CoolPotOS Vlang Edition - 由Vlang语言编写的64位版本, 由 <code>wenxuanjun</code> 负责主要开发</li></ul><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h2><p>CoolPotOS目前仅提供可引导光盘映像文件,接下来让我们了解如何下载 CoolPotOS 的光盘映像文件</p><ul><li><p><a href="https://github.com/plos-clan/CoolPotOS/releases" target="_blank" rel="noreferrer">GitHub/Release</a> GitHub 存储库的发行版列表, 一般是比较稳定的版本</p></li><li><p><a href="https://github.com/plos-clan/CoolPotOS/actions" target="_blank" rel="noreferrer">GitHub/Actions</a> GitHub 工作流构建后提供的可引导光盘映像, 一般针对于该递交的构建</p></li></ul><h2 id="boot-on-virtual-machine" tabindex="-1">Boot on virtual machine <a class="header-anchor" href="#boot-on-virtual-machine" aria-label="Permalink to &quot;Boot on virtual machine&quot;">​</a></h2><p>在x86仿真模拟的一些虚拟机上, 您可以直接指定CoolPotOS的光盘映像来引导</p><ul><li><code>qemu</code> 使用 <code>-cdrom</code> 可以指定</li><li><code>VMware</code> 可以在 <code>编辑虚拟机设置</code> 指定 CD/DVD 设备</li></ul><h2 id="boot-on-physical-machines" tabindex="-1">Boot on physical machines <a class="header-anchor" href="#boot-on-physical-machines" aria-label="Permalink to &quot;Boot on physical machines&quot;">​</a></h2><p>如果想要在真机启动CoolPotOS, 首先要确保您的CPU支持x86指令集。<br> 然后我们可以找一块闲置的U盘, 刷入 <code>Ventory</code>后将CoolPotOS的映像放入该U盘中即可引导。</p><div class="warning custom-block"><p class="custom-block-title">不要做傻事</p><p>CoolPotOS 性质即仅作交流学习使用, 不要作死将CoolPotOS刷进主盘当作主力操作系统。 <br> 由此行为引发的一些列诸如数据丢失的后果我们概不负责。</p></div>',13)]))}const b=a(i,[["render",r]]);export{p as __pageData,b as default};
